{"task": "Find log messages that contain AWS access key IDs", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'AKIA[0-9A-Z]{16}')"}
{"task": "Find log messages that contain a generic API key or token assignment pattern", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '(?i)(api[_-]?key|token)\\s*[=:]\\s*[A-Za-z0-9_\\-]{16,}')"}
{"task": "Find log messages that contain what looks like a 16-digit credit card number", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '\\b(?:[0-9]{4}[- ]?){3}[0-9]{4}\\b')"}
{"task": "Find log messages that contain a private key block header", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '-----BEGIN (RSA |EC |)PRIVATE KEY-----')"}
{"task": "Count how many log entries per service contain a password field with a value", "sql": "SELECT service, count(*) AS leak_count FROM logs WHERE regexp_like(message, '(?i)password\\s*[=:]\\s*\\S+') GROUP BY service"}
{"task": "Classify log messages by secret type using regexp_like in a CASE expression", "sql": "SELECT ts, service, message, CASE WHEN regexp_like(message, 'AKIA[0-9A-Z]{16}') THEN 'aws_key' WHEN regexp_like(message, '(?i)secret[_-]?key\\s*[=:]') THEN 'secret_key' WHEN regexp_like(message, '\\b(?:[0-9]{4}[- ]?){3}[0-9]{4}\\b') THEN 'card_number' ELSE 'other' END AS leak_type FROM logs WHERE regexp_like(message, '(?i)(AKIA[0-9A-Z]{16}|secret[_-]?key\\s*[=:]|\\b(?:[0-9]{4}[- ]?){3}[0-9]{4}\\b)')"}
{"task": "Find error-level logs that also look like they expose a bearer token", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, 'Bearer\\s+[A-Za-z0-9\\-_.]{20,}')"}
{"task": "Find request paths containing query-string parameters that look like leaked tokens or keys", "sql": "SELECT id, user_id, path, status FROM events WHERE regexp_like(path, '(?i)[?&](token|api[_-]?key|access[_-]?token)=[A-Za-z0-9\\-_.]{10,}')"}
{"task": "Find log messages that mention a database connection string with an embedded password", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '(?i)(postgres|mysql|mongodb)://[^:\\s]+:[^@\\s]+@')"}
{"task": "List distinct services with a daily count of messages matching any PII-like regex, ordered by most recent day", "sql": "SELECT date_trunc('day', ts) AS day, service, count(*) AS matches FROM logs WHERE regexp_like(message, '(?i)(ssn|social security)\\s*[:=]?\\s*\\d{3}-?\\d{2}-?\\d{4}') GROUP BY day, service ORDER BY day DESC"}

